<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,shallowRef} from 'vue'
import {parseAssessmentStatus,type AssessmentStatus,type PauseInterval} from './assessmentDTO'
const emit=defineEmits<{'session-expired':[]}>()
type Session={subject_id:string;org_id:string;auth_epoch:string;csrf_token:string;mfa_recent:boolean;interview_permissions:{capability:string;category:string}[]}
type Job={id:string;employee_id:string;window_id:string;result_id?:string;state:string;provider_policy_id:string;audience:string;attempt:number;max_attempts:number;created_at:string;completed_at?:string;error_code?:string}
type Document={summary:string;claims:string[];sources:{kind:string;id:string;version:string}[]}
type Result={id:string;job_id:string;status:string;revision:string;document:Document;created_at:string;updated_at:string}
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const status=shallowRef<AssessmentStatus|null>(null),session=shallowRef<Session|null>(null),jobs=shallowRef<Job[]>([]),selected=shallowRef<Result|null>(null)
const employee=ref(''),phase=ref<'idle'|'loading'|'saving'>('idle'),message=ref(''),approvalInput=ref(''),draftText=ref('')
const form=reactive({unit:'',count:null as number|null,anchor:'',timezone:'',offset:null as number|null,due:'',through:'',pauses:'',ai:'',started:false,ended:false,note:false,service:'',provider:'',audience:'manager_followup',expires:''})
let alive=false,generation=0,controller:AbortController|null=null,policyAttempt:{employee:string;key:string;body:string}|null=null
const has=(capability:string)=>Boolean(session.value?.interview_permissions.some(p=>p.capability===capability&&p.category==='metadata'))
const canManage=computed(()=>has('interview_policy.manage')),canRequest=computed(()=>has('assessment.request')),canApprove=computed(()=>has('assessment.input.approve')),canRead=computed(()=>has('assessment.read')),canPublish=computed(()=>has('assessment.publish'))
const explicitPolicy=computed(()=>['day','week','month'].includes(form.unit)&&form.count!==null&&Number.isInteger(form.count)&&form.count>0&&Boolean(form.anchor&&form.timezone&&form.due&&form.through)&&form.offset!==null&&Number.isInteger(form.offset)&&form.offset>=0&&['disabled','manual_approved','periodic_structured_v1'].includes(form.ai)&&(form.started||form.ended||form.note)&&(form.ai!=='periodic_structured_v1'||Boolean(uuid.test(form.service)&&uuid.test(form.provider)&&form.expires&&['employee_followup','manager_followup'].includes(form.audience))))
function cancel(){generation++;controller?.abort();controller=null;phase.value='idle'}
function begin(next:'loading'|'saving'){cancel();controller=new AbortController();phase.value=next;message.value='';return{generation,signal:controller.signal}}
function current(op:{generation:number;signal:AbortSignal}){return alive&&op.generation===generation&&!op.signal.aborted}
function clear(){status.value=null;session.value=null;jobs.value=[];selected.value=null;message.value=''}
function apply(){const p=status.value?.policy;if(!p)return;form.unit=p.cadence.unit;form.count=p.cadence.count;form.anchor=p.anchor_date;form.timezone=p.timezone;form.offset=p.due_offset_days;form.due=p.local_due_time;form.through=p.window_through;form.pauses=p.pause_intervals.map(x=>`${x.from},${x.to}`).join('\n');form.ai=p.ai_mode;form.started=p.required_fields.includes('actual_started_at');form.ended=p.required_fields.includes('actual_ended_at');form.note=p.required_fields.includes('shared_published_note');const standing=(p as unknown as {standing_policy?:{service_subject_id:string;provider_policy_id:string;audience:string;expires_at:string}}).standing_policy;if(standing){form.service=standing.service_subject_id;form.provider=standing.provider_policy_id;form.audience=standing.audience;form.expires=standing.expires_at}}
async function json(path:string,op:{generation:number;signal:AbortSignal},init:RequestInit={}){const response=await fetch(`/api/v1${path}`,{credentials:'same-origin',cache:'no-store',signal:op.signal,...init,headers:{'X-Access-Purpose':'interview_followup',...(init.headers??{})}});if(!current(op))throw new DOMException('cancelled','AbortError');if(response.status===401){emit('session-expired');throw new Error('expired')}if(!response.ok)throw new Error(String(response.status));if(response.status===204)return null;return response.json()}
async function load(){if(!employee.value)return;const op=begin('loading');try{const s=await json(`/session?employee_id=${employee.value}`,op) as Session;if(!s||!uuid.test(s.subject_id)||typeof s.csrf_token!=='string'||typeof s.mfa_recent!=='boolean'||!Array.isArray(s.interview_permissions))throw new Error('503');session.value=s;const parsed=parseAssessmentStatus(await json(`/employees/${employee.value}/interview-status`,op));if(!parsed)throw new Error('503');status.value=parsed;apply();jobs.value=has('assessment.read')?await json(`/employees/${employee.value}/assessment-jobs`,op) as Job[]:[]}catch(error){if(current(op)&&!(error instanceof DOMException)){clear();message.value=error instanceof Error&&error.message==='expired'?'会话已失效。':'无法读取跟进状态。'}}finally{if(current(op)){phase.value='idle';controller=null}}}
function pauses():PauseInterval[]{if(!form.pauses.trim())return[];return form.pauses.split('\n').map(line=>{const [from,to,...rest]=line.split(',').map(x=>x.trim());if(!from||!to||rest.length)throw new Error('pause');return{from,to}})}
function headers(){return{'Content-Type':'application/json','X-CSRF-Token':session.value!.csrf_token,'Idempotency-Key':crypto.randomUUID()}}
async function save(){if(!session.value||!status.value||!canManage.value)return;if(!explicitPolicy.value){message.value='请明确选择周期、时区、截止、AI 模式及至少一项完成事实；周期自动化还必须填写服务主体、供应商策略、受众和期限。';return}const op=begin('saving');try{const required:string[]=[];if(form.started)required.push('actual_started_at');if(form.ended)required.push('actual_ended_at');if(form.note)required.push('shared_published_note');const standing=form.ai==='periodic_structured_v1'?{service_subject_id:form.service,provider_policy_id:form.provider,audience:form.audience,expires_at:new Date(form.expires).toISOString(),template_version:'periodic_structured_v1'}:undefined;const body=JSON.stringify({expected_revision:status.value.policy?.revision??'0',cadence:{unit:form.unit,count:Number(form.count)},anchor_date:form.anchor,timezone:form.timezone,due_offset_days:Number(form.offset),local_due_time:form.due,window_through:form.through,pause_intervals:pauses(),purpose:'interview_followup',ai_mode:form.ai,required_fields:required,standing_policy:standing});if(!policyAttempt||policyAttempt.employee!==employee.value||policyAttempt.body!==body)policyAttempt={employee:employee.value,key:crypto.randomUUID(),body};await json(`/employees/${employee.value}/interview-policy`,op,{method:'PUT',headers:{...headers(),'Idempotency-Key':policyAttempt.key},body:policyAttempt.body});policyAttempt=null;if(current(op)){controller=null;phase.value='idle';await load()}}catch(error){if(current(op)&&!(error instanceof DOMException)){phase.value='idle';controller=null;const code=error instanceof Error?error.message:'';if(/^4\d\d$/.test(code))policyAttempt=null;message.value=code==='409'?'策略版本已变化，请刷新后重试。':policyAttempt?'保存结果不确定；再次保存将使用同一幂等请求确认。':'策略未保存，请检查策略、期限及权限。'}}}
async function requestAssessment(windowId:string){if(!session.value)return;const op=begin('saving');try{const out=await json(`/employees/${employee.value}/assessments/request`,op,{method:'POST',headers:headers(),body:JSON.stringify({window_id:windowId})}) as {id:string};approvalInput.value=out.id;message.value='最小结构化输入已生成；必须由另一位具备批准权限的人员批准。'}catch(e){if(current(op))message.value=`生成输入失败（${e instanceof Error?e.message:'unknown'}）。`}finally{if(current(op)){phase.value='idle';controller=null}}}
async function approve(){if(!session.value||!approvalInput.value||!form.provider)return;const op=begin('saving');try{await json(`/employees/${employee.value}/assessment-inputs/approve`,op,{method:'POST',headers:headers(),body:JSON.stringify({input_id:approvalInput.value,provider_policy_id:form.provider,audience:form.audience})});approvalInput.value='';if(current(op)){controller=null;phase.value='idle';await load()}}catch(e){if(current(op))message.value=`批准失败（${e instanceof Error?e.message:'unknown'}）；请求人不能自行批准。`}finally{if(current(op)){phase.value='idle';controller=null}}}
async function openResult(id:string){const op=begin('loading');try{selected.value=await json(`/employees/${employee.value}/assessment-results/${id}`,op) as Result;draftText.value=JSON.stringify(selected.value.document,null,2)}catch(e){if(current(op))message.value=`读取草稿失败（${e instanceof Error?e.message:'unknown'}）。`}finally{if(current(op)){phase.value='idle';controller=null}}}
async function transition(action:'edit'|'publish'|'discard'){if(!session.value||!selected.value)return;const op=begin('saving');try{let document=selected.value.document;if(action==='edit')document=JSON.parse(draftText.value) as Document;selected.value=await json(`/employees/${employee.value}/assessment-results/${selected.value.id}`,op,{method:'POST',headers:headers(),body:JSON.stringify({result_id:selected.value.id,expected_revision:selected.value.revision,action,document})}) as Result;if(current(op)){controller=null;phase.value='idle';await load()}}catch(e){if(current(op))message.value=`草稿操作失败（${e instanceof Error?e.message:'unknown'}）。`}finally{if(current(op)){phase.value='idle';controller=null}}}
function route(){cancel();clear();const match=/^\/employees\/([0-9a-f-]+)\/followup\/?$/.exec(location.pathname);employee.value=match?.[1]??'';if(employee.value)void load()}
onMounted(()=>{alive=true;addEventListener('popstate',route);route()});onBeforeUnmount(()=>{alive=false;removeEventListener('popstate',route);cancel();clear()})
</script>
<template><main><header><p class="eyebrow">面谈跟进 · 明确事实</p><h1>周期、评估队列与人工复核</h1><p>只向受控 worker 提供计划窗口、实际状态、回填标记和行动项计数；姓名、职称、笔记正文、财务与健康信息不进入自动输入。不推断绩效、情绪或人员结论。</p></header><p v-if="message" role="alert">{{message}}</p><p v-if="phase!=='idle'" role="status">{{phase==='saving'?'正在提交…':'正在读取状态…'}}</p><template v-if="status"><section><h2>状态与覆盖</h2><p><strong>{{status.state==='configured'?'已配置':'未配置'}}</strong> · 面谈 {{status.coverage.interviews}} · 行动项 {{status.coverage.actions}} · 笔记 {{status.coverage.notes}}</p><p>AI：{{status.ai_state}}<span v-if="status.ai_block_reason">（{{status.ai_block_reason}}）</span></p></section><section><h2>窗口事实与最小输入</h2><p v-if="!status.items.length">尚无窗口。</p><article v-for="item in status.items" :key="item.window.id"><strong>{{item.window.local_start}} → {{item.window.local_end}} · {{item.state}}</strong><span>计划 {{item.facts.scheduled_count}}；发生 {{item.facts.occurred_count}}；完整 {{item.facts.complete_count}}；不完整 {{item.facts.incomplete_count}}；未知 {{item.facts.unknown_count}}</span><span>开放行动 {{item.facts.open_action_count}}；逾期 {{item.facts.overdue_action_count}}</span><button v-if="canRequest&&!item.window.paused" :disabled="phase!=='idle'" @click="requestAssessment(item.window.id)">生成待批准输入</button></article></section><section v-if="canApprove"><h2>独立输入批准</h2><p>输入 ID 可由请求人安全转交；同一主体不能请求并批准。</p><form @submit.prevent="approve"><label>输入 ID<input v-model="approvalInput" required></label><label>供应商策略 ID<input v-model="form.provider" required></label><label>受众<select v-model="form.audience"><option value="manager_followup">经理跟进</option><option value="employee_followup">员工跟进</option></select></label><button :disabled="phase!=='idle'||!session?.mfa_recent">批准并入队</button></form></section><section v-if="canRead"><h2>持久任务与草稿</h2><p v-if="!jobs.length">尚无任务。</p><article v-for="job in jobs" :key="job.id"><strong>{{job.state}} · 尝试 {{job.attempt}}/{{job.max_attempts}}</strong><span>窗口 {{job.window_id}} · 受众 {{job.audience}}</span><span v-if="job.error_code">{{job.error_code}}</span><button v-if="job.result_id" @click="openResult(job.result_id)">打开人工复核</button></article><form v-if="selected"><strong>结果 {{selected.status}} · rev {{selected.revision}}</strong><textarea v-model="draftText" rows="12" aria-label="评估草稿 JSON"></textarea><button v-if="selected.status==='draft'" @click.prevent="transition('edit')">保存人工修改</button><button v-if="selected.status==='draft'&&canPublish" :disabled="!session?.mfa_recent" @click.prevent="transition('publish')">发布</button><button v-if="selected.status==='draft'&&canPublish" @click.prevent="transition('discard')">丢弃</button></form></section><section v-if="canManage"><h2>跟进策略</h2><p v-if="!session?.mfa_recent">保存需要近期可信 MFA；请先在页面顶部重新验证。</p><form @submit.prevent="save"><label>周期<select v-model="form.unit"><option value="day">日</option><option value="week">周</option><option value="month">月</option></select></label><label>间隔<input v-model.number="form.count" type="number" min="1" max="365" required></label><label>锚点<input v-model="form.anchor" type="date" required></label><label>IANA 时区<input v-model="form.timezone" required></label><label>截止偏移天数<input v-model.number="form.offset" type="number" min="0" max="365" required></label><label>当地截止时间<input v-model="form.due" type="time" required></label><label>生成至<input v-model="form.through" type="date" required></label><label>AI 模式<select v-model="form.ai"><option value="disabled">禁用</option><option value="manual_approved">仅人工批准</option><option value="periodic_structured_v1">周期结构化</option></select></label><template v-if="form.ai==='periodic_structured_v1'"><label>服务主体 ID<input v-model="form.service" required></label><label>供应商处理策略 ID<input v-model="form.provider" required></label><label>受众<select v-model="form.audience"><option value="manager_followup">经理跟进</option><option value="employee_followup">员工跟进</option></select></label><label>授权截止<input v-model="form.expires" type="text" placeholder="2026-12-12T00:00:00Z" required></label></template><label class="wide">暂停区间（每行 from,to）<textarea v-model="form.pauses" placeholder="2026-12-20,2027-01-05"></textarea></label><fieldset><legend>完成所需事实</legend><label><input v-model="form.started" type="checkbox">实际开始</label><label><input v-model="form.ended" type="checkbox">实际结束</label><label><input v-model="form.note" type="checkbox">已发布共享笔记</label></fieldset><button :disabled="phase!=='idle'||!session?.mfa_recent||!explicitPolicy">保存策略</button></form></section></template></main></template>
<style scoped>main{max-width:76rem;margin:auto;padding:1rem;font-family:system-ui;color:#17212b}header,section{border:1px solid #ccd6df;border-radius:.7rem;padding:1rem;margin:1rem 0;background:#fff}.eyebrow{font-weight:800;color:#176553}article,form{display:grid;gap:.65rem;margin:.7rem 0;padding:.7rem;border:1px solid #dbe3ea;border-radius:.45rem}article span{display:block}form{grid-template-columns:repeat(auto-fit,minmax(13rem,1fr))}label{display:grid;gap:.25rem}.wide,fieldset{grid-column:1/-1}input,select,textarea,button{font:inherit;padding:.5rem;border:1px solid #8ba0b2;border-radius:.35rem}button{background:#176553;color:white;border:0;font-weight:700}button:disabled{opacity:.55}</style>
